  i.ITEMID AS MATERIAL, r.TRANDATE AS GR_DATE, l.QUANTITY AS GR_QTY, l.QUANTITY * l.RATE AS GR_VALUE, r.CURRENCY
FROM {{ source('src_netsuite', 'transactionline') }} l JOIN {{ source('src_netsuite', 'transaction') }} r ON r.ID = l.TRANSACTION JOIN {{ source('src_netsuite', 'transaction') }} po ON po.ID = r.CREATEDFROM
